import { expect, expectStatus, test } from "../../fixtures";

test("a page past the last vendor is empty but still reports the total", { tag: "@LIF-15" }, async ({ apiAs }) => {
  // Arrange: learn the total from the first page, then pick an offset well beyond it.
  const member = await apiAs("member");
  const firstPage = await expectStatus<{ items: unknown[]; total: number }>(
    await member.get("/api/vendors", { params: { limit: 20, offset: 0 } }),
    200,
  );
  const beyondOffset = firstPage.total + 1000;

  // Act: list the page that starts past the last vendor.
  const response = await member.get("/api/vendors", { params: { limit: 20, offset: beyondOffset } });

  // Assert: the page is empty, but the total matches the first page.
  const page = await expectStatus<{ items: unknown[]; total: number }>(response, 200);
  expect(page.items).toEqual([]);
  expect(page.total).toBe(firstPage.total);
});
